@@ -0,0 +1,15 @@
+import XCTest
+
+final class RunnerMessagesUITests: XCTestCase {
+    func testOpenMessages() {
+        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
+        app.launch()
+
+        let messagesTab = app.buttons["Messages"]
+        if messagesTab.waitForExistence(timeout: 10) {
+            messagesTab.tap()
+        } else {
+            app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.93)).tap()
+        }
+    }
+}
